E,EAAKlxB,QACRyzB,EAAMtnC,YAAY2pC,CAAe,EAElCrC,EAAMtnC,YAAY4pC,CAAK,EACvBtsC,EAAS,KAAMiK,CAAM,EAIvB,CAAC,CACF,EACAggC,aAAc,SAASttC,EAASqD,GAC/ByB,IAAIgmC,EAAOvrC,KACP,CAAEqhB,KAAAA,EAAMysB,MAAAA,CAAM,EAAIrtC,EACtB4C,UAAUme,SAAS6E,MAAMzC,YAAYvC,EAAK+K,QAAS,CAClD/R,OAAQkxB,EAAKlxB,MACd,EAAG,SAAUzY,EAAKmM,GACjB,IAEKoiC,EAFAvuC,EAkBJkC,EAASlC,EAAK,IAAI,GAjBdwuC,EAAQ3qC,SAASY,cAAc,KAAK,EACpC8pC,EAAkB1qC,SAASY,cAAc,KAAK,EAClD+pC,EAAMrqC,IAAMgI,EACZoiC,EAAgBpqC,IAAM1C,UAAUme,SAASyD,UAAU5D,EAAK+K,QAAS,CAChE/R,OAAQla,KAAK6vC,KAAKzE,EAAKlxB,OAAS,EAAE,EAClC+J,MAAOjkB,KAAK6vC,KAAKzE,EAAKnnB,MAAQ,EAAE,EAChCQ,KAAM,EACP,CAAC,EACDwrB,EAAMC,IAAMF,EAAgBE,IAAMhvB,EAAKxY,OAAS,GAChDsnC,EAAgBtS,UAAY,2BAC5BsS,EAAgB/9B,aAAa,2CAA4Cm5B,EAAKlxB,kEAAkE,EAChJ+1B,EAAM16B,MAAM2xB,UAAY,gBACxByG,EAAM17B,aAAa,QAAS,4CAA4C,EACxE07B,EAAMtnC,YAAY2pC,CAAe,EACjCrC,EAAMtnC,YAAY4pC,CAAK,EACvBtsC,EAAS,KAAMiK,CAAM,EAIvB,CAAC,CACF,EACA89B,sBAAuB,WACtBtmC,IAAIgmC,EAAOvrC,KAEXA,KAAK4rC,SAASxjC,iBAAiB,oBAAqB,WAC9CmjC,EAAKsE,gBACTtE,EAAKsE,cAAgB,CAAA,EAEvB,CAAC,EACD7vC,KAAK4rC,SAASxjC,iBAAiB,mBAAoB,WAClDuG,WAAW,KACV48B,EAAKsE,cAAgB,CAAA,CACtB,EAAG,CAAC,CACL,CAAC,EACGtE,EAAKluB,OAAOowB,iBACflC,EAAKK,SAASxjC,iBAAiB,mBAAoB,WAClD,IACImoC,EADChF,EAAKuD,gBACNyB,EAAWhF,EAAKsD,WAAWlE,YAAY,EAAIY,EAAKluB,OAAOixB,kBAC3D/C,EAAKuD,cAAclB,WAAWvoC,QAAQ,SAAUkpC,GAAOA,EAAIpe,UAAUmD,OAAO,QAAQ,CAAG,CAAC,EACxFiY,EAAKuD,cAAclB,WAAW2C,GAAUpgB,UAAUjmB,IAAI,QAAQ,EAC/D,CAAC,EACDqhC,EAAKK,SAASxjC,iBAAiB,iBAAkB,WAC3CmjC,EAAKuD,gBACVvD,EAAKuD,cAAclB,WAAWvoC,QAAQ,SAAUkpC,GAAOA,EAAIpe,UAAUmD,OAAO,QAAQ,CAAG,CAAC,EACxFiY,EAAKuD,cAAclB,WAAW,GAAGzd,UAAUjmB,IAAI,QAAQ,EACxD,CAAC,EAEH,CACD","file":"buildfire_lightcarousel.min.js","sourcesContent":["//\"use strict\";\n\nfunction Packet(id, cmd, data) {\n\tthis.id = id ? id : new Date().toISOString() + Math.random();\n\tthis.cmd = cmd;\n\tthis.data = data;\n\tthis.instanceId = null;\n}\n\n/**\n * The error every failed contract operation invoke ends with (buildfire.services.contract.invoke).\n *\n *   new ContractOperationInvokeError({\n *       message: 'error field length',\n *       code: ContractOperationInvokeError.CODES.VALIDATION,\n *       context: { source: ContractOperationInvokeError.SOURCES.PLUGIN }\n *   });\n *\n * A plugin implementing an operation (window.widgetContract / window.controlContract) can fail it with one\n * of these to give the caller a code; anything else it fails with (a string, an Error, a rejection, a throw)\n * reaches the caller as one too, with code UNKNOWN.\n *\n * It crosses frames as plain data (toJSON) — postMessage drops the prototype — and is rebuilt into an\n * instance on the caller's side (ContractOperationInvokeError.from), so `err instanceof\n * ContractOperationInvokeError` holds for the caller.\n */\nclass ContractOperationInvokeError extends Error {\n\t/**\n\t * @param {Object|String} [options] the options, or just the message\n\t * @param {String} [options.message]\n\t * @param {String} [options.code] one of ContractOperationInvokeError.CODES; UNKNOWN when left out or not one of them\n\t * @param {Object} [options.context] where it failed: { source, functionName, ... }; source defaults to PLUGIN\n\t */\n\tconstructor(options) {\n\t\tif (typeof (options) === 'string') options = { message: options };\n\t\toptions = options || {};\n\t\tsuper(options.message || 'contract operation failed');\n\t\tthis.name = 'ContractOperationInvokeError';\n\t\tthis.code = ContractOperationInvokeError.isCode(options.code) ? options.code : ContractOperationInvokeError.CODES.UNKNOWN;\n\t\tthis.context = Object.assign({ source: ContractOperationInvokeError.SOURCES.PLUGIN }, options.context || {});\n\t}\n\n\t// the plain shape it travels as between frames\n\ttoJSON() {\n\t\treturn { name: this.name, message: this.message, code: this.code, context: this.context };\n\t}\n\n\tstatic isCode(code) {\n\t\treturn Object.keys(ContractOperationInvokeError.CODES).some(function (key) {\n\t\t\treturn ContractOperationInvokeError.CODES[key] === code;\n\t\t});\n\t}\n\n\t/**\n\t * Any error a contract invoke can end with, as a ContractOperationInvokeError: an instance is returned as\n\t * is, its wire shape ({ message, code, context }) is rebuilt, and anything else (a string, an Error) gets\n\t * code UNKNOWN. defaultContext fills only what the error does not already say.\n\t */\n\tstatic from(err, defaultContext) {\n\t\tif (!err) return err;\n\t\tif (err instanceof ContractOperationInvokeError) return err;\n\t\tvar isObject = typeof (err) === 'object';\n\t\tvar message = typeof (err) === 'string' ? err\n\t\t\t: (isObject && err.message) ? err.message\n\t\t\t\t: (isObject ? JSON.stringify(err) : String(err));\n\t\treturn new ContractOperationInvokeError({\n\t\t\tmessage: message,\n\t\t\tcode: isObject ? err.code : null,\n\t\t\tcontext: Object.assign({}, defaultContext || {}, (isObject && err.context) || {})\n\t\t});\n\t}\n}\n\n// Generic, reusable codes — the same few for every operation of every plugin.\n// Kept in sync with ContractAPI.INVOKE_ERROR_CODES (app/scripts/framework/pluginAPI/contractAPI.js).\nContractOperationInvokeError.CODES = Object.freeze({\n\tNOT_FOUND: 'notFound',             // the instance, the operation, its function, or a record it looked up does not exist\n\tVALIDATION: 'validation',          // the call or its parameters are invalid (missing, wrong type, length, count...)\n\tNOT_SUPPORTED: 'notSupported',     // the operation declares something this platform cannot run (type, storage service, query)\n\tNOT_ALLOWED: 'notAllowed',         // it may not run from here, or the user may not do it (wrong host, read-only store, permission denied)\n\tUNAUTHENTICATED: 'unauthenticated', // it needs a logged in user and there is none, or sign-in failed\n\tALREADY_EXISTS: 'alreadyExists',   // what it would create already exists\n\tCONFLICT: 'conflict',              // the data changed under it, or the request clashes with the current state\n\tLIMIT_EXCEEDED: 'limitExceeded',   // a quota, rate or size limit was hit\n\tCANCELLED: 'cancelled',            // the user (or the plugin) cancelled it, e.g. closed a foreground dialog\n\tTIMEOUT: 'timeout',                // no result arrived within the time allowed\n\tNOT_AVAILABLE: 'notAvailable',     // it cannot run right now (its frame failed to load or closed, a service is missing)\n\tNETWORK: 'network',                // a request it depends on failed to go through\n\tINVALID_CONTRACT: 'invalidContract', // the plugin's contract files are missing a field, malformed, or not valid JSON\n\tINVALID_RESULT: 'invalidResult',   // it ran, but its result cannot be returned (not serializable, projection failed)\n\tINTERNAL: 'internal',              // code threw while running it (the plugin's function, or the app's)\n\tUNKNOWN: 'unknown'                 // failed without saying why (a plain string, an untyped rejection)\n});\n\n// Which side the error came from, in context.source.\nContractOperationInvokeError.SOURCES = Object.freeze({\n\tPLUGIN: 'plugin', // the plugin's own operation code\n\tAPP: 'app',       // the app / control panel running the call\n\tSDK: 'sdk'        // the caller's SDK, before the call was sent\n});\n\nif (typeof (window) !== 'undefined') window.ContractOperationInvokeError = ContractOperationInvokeError;\n\n/// ref: https://github.com/BuildFire/sdk/wiki\nvar buildfire = {\n\tisFileServer: function(url){\n\t\treturn (url.indexOf('s3.amazonaws.com') !== -1);\n\t}\n\t, isWidget: function() {\n\t\treturn window.location.href.indexOf('/widget/') > 0;\n\t}\n\t, isWidgetService: function() {\n\t\treturn buildfire.isWidget() && window.location.href.indexOf('/widget/index.html') < 0;\n\t}\n\t, isWeb: function(callback){\n\t\tvar isWebFromContext = function (context) {\n\t\t\tif (context && context.device && context.device.platform) {\n\t\t\t\treturn context.device.platform.toLowerCase() === 'web';\n\t\t\t} else {\n\t\t\t\tconsole.error('context device platform not defined');\n\t\t\t\treturn (window.location.protocol.indexOf('http') === 0);\n\t\t\t}\n\t\t};\n\t\tvar context = buildfire.getContext(function(err, callbackContext){\n\t\t\tif(callback){\n\t\t\t\tif(err) {\n\t\t\t\t\tcallback(err);\n\t\t\t\t} else {\n\t\t\t\t\tcallback(null, isWebFromContext(callbackContext));\n\t\t\t\t}\n\t\t\t}\n\t\t});\n\t\tif(context) {\n\t\t\treturn isWebFromContext(context);\n\t\t} else {\n\t\t\tif(!callback) {\n\t\t\t\tconsole.warn('context not ready. must use isWeb with callback parameter: function(err, isWebResult)');\n\t\t\t\treturn (window.location.protocol.indexOf('http') === 0);\n\t\t\t}\n\t\t\t// don't return anything if context is not ready but we have a callback\n\t\t}\n\n\t},\n\t_lazyScriptsQueues: {},\n\tlazyLoadScript: function({ relativeScriptsUrl, scriptId }, readyCallback) {\n\t\tif (!this._lazyScriptsQueues[scriptId]) {\n\t\t\tthis._lazyScriptsQueues[scriptId] = { loaded: false, queue:[] };\n\t\t} else if (this._lazyScriptsQueues[scriptId].loaded && readyCallback) {\n\t\t\treturn readyCallback();\n\t\t}\n\n\n\t\tconst lazyQueue = this._lazyScriptsQueues[scriptId];\n\t\tlazyQueue.queue.push(readyCallback);\n\n\t\tif (lazyQueue.queue.length > 1) {\n\t\t\treturn;\n\t\t}\n\t\tconst url = buildfire.getContext().type === 'control' ?\n\t\t\t`../../../../scripts/${relativeScriptsUrl}`\n\t\t\t: `../../../scripts/${relativeScriptsUrl}`;\n\n\t\tconst _executeQueue = (err) => {\n\t\t\tlazyQueue.queue.forEach((callback) => {\n\t\t\t\tif (callback) callback(err);\n\t\t\t});\n\t\t\tlazyQueue.loaded = true;\n\t\t\tlazyQueue.queue = []; // clear queue\n\t\t};\n\t\tbuildfire.loadScript({ url, scriptId }, _executeQueue);\n\t},\n\tloadScript: function({ url, scriptId }, callback = Function()) {\n\t\tlet script = document.getElementById(scriptId);\n\t\tconst scripts = document.getElementsByTagName('script');\n\n\t\t// script exist\n\t\tif (script ||  Array.from(scripts).some((s) =>  s.src.includes(url.replaceAll(\"../\", \"\")))) {\n\t\t\treturn callback();\n\t\t}\n\n\t\tconst parentElement = (document.head || document.body);\n\t\tscript = document.createElement('script');\n\t\tscript.id = scriptId || '';\n\t\tscript.type = 'text/javascript';\n\t\tscript.src = url;\n\t\tscript.onload = callback;\n\t\tscript.onerror = function () {\n\t\t\tcallback(new Error('failed to load script component'));\n\t\t\tconsole.error('failed to load script component');\n\t\t};\n\t\tparentElement.appendChild(script);\n\t}, ratingSystem: {\n\t\tinject: function () {\n\t\t\tif (typeof buildfire === 'undefined') return;\n\t\t\tif (typeof (buildfire.components) == 'undefined' || typeof (buildfire.components.ratingSystem) == 'undefined') {\n\t\t\t\tloadScript('../../../scripts/buildfire/components/ratingSystem/index.min.js', function (err) {\n\t\t\t\t\tvar parentElement = (document.head || document.body);\n\t\t\t\t\tvar link = document.createElement('link');\n\t\t\t\t\tlink.rel = 'stylesheet';\n\t\t\t\t\tlink.type = 'text/css';\n\t\t\t\t\tlink.href = '../../../scripts/buildfire/components/ratingSystem/index.min.css';\n\t\t\t\t\tparentElement.appendChild(link);\n\t\t\t\t\t// utf-8 encoding is necessary for the rating system to function\n\t\t\t\t\tconst charset = parentElement.querySelector('meta[charset]');\n\t\t\t\t\tif (!charset || !charset.getAttribute('charset').toLowerCase().includes('utf-8')) {\n\t\t\t\t\t\tconsole.warn('UTF-8 charset is required for ratingSystem to function properly');\n\t\t\t\t\t}\n\t\t\t\t\tbuildfire.components.ratingSystem.injectRatings({ isFromWysiwyg: true });\n\t\t\t\t});\n\t\t\t} else buildfire.components.ratingSystem.injectRatings({ isFromWysiwyg: true });\n\n\t\t\tfunction hasScript(url) {\n\t\t\t\twhile (url.includes('../')) url = url.replace('../', '');\n\t\t\t\tvar scripts = document.getElementsByTagName('script');\n\t\t\t\tfor (var i = 0; i < scripts.length; i++) {\n\t\t\t\t\tif(scripts[i].src.includes(url)) return true;\n\t\t\t\t}\n\t\t\t\treturn false;\n\t\t\t}\n\n\t\t\tfunction loadScript(url, callback) {\n\t\t\t\tif(hasScript(url)) re